    {"code": "SHOP_POWER_RESERVE","name": "Запас мощности не менее 25 процентов","parameters": [{"code": "available","dataType": "NUMBER"},{"code": "load","dataType": "NUMBER"}],"expression": {"kind": "OPERATOR","operator": "GE","args": [{"kind": "FORMAL","formalCode": "available"},{"kind": "OPERATOR","operator": "MUL","args": [{"kind": "FORMAL","formalCode": "load"},{"kind": "CONST","value": 1.25}]}]}},
