    {"code": "SHOP-WORKPLACE","name": "Мобильное рабочее место","parent": "LAPTOPS","parameters": [{"code": "ram","name": "Оперативная память","type": "INTEGER","unit": "GB","min": 16,"max": 64,"enumeration": null},{"code": "ssd","name": "Объём SSD","type": "INTEGER","unit": "GB","min": 512,"max": 2048,"enumeration": null},{"code": "dock","name": "Док-станция USB-C","type": "BOOLEAN","unit": null,"min": null,"max": null,"enumeration": null},{"code": "monitors","name": "Внешние мониторы","type": "INTEGER","unit": null,"min": 0,"max": 2,"enumeration": null},{"code": "charger","name": "Мощность зарядного устройства","type": "INTEGER","unit": "W","min": 65,"max": 140,"enumeration": null},{"code": "keyboard","name": "Раскладка","type": "ENUM","unit": null,"min": null,"max": null,"enumeration": "SHOP-KEYBOARD"}],"rules": [{"code": "AVAILABLE_OPTIONS","name": "Доступные конфигурации","message": "Выберите RAM 16/32/64 ГБ, SSD 512/1024/2048 ГБ и зарядное устройство 65/100/140 Вт","expression": {"kind": "OPERATOR","operator": "AND","args": [{"kind": "OPERATOR","operator": "IN","args": [{"kind": "PARAMETER","parameterCode": "ram"},{"kind": "CONST","value": [16,32,64]}]},{"kind": "OPERATOR","operator": "IN","args": [{"kind": "PARAMETER","parameterCode": "ssd"},{"kind": "CONST","value": [512,1024,2048]}]},{"kind": "OPERATOR","operator": "IN","args": [{"kind": "PARAMETER","parameterCode": "charger"},{"kind": "CONST","value": [65,100,140]}]}]}},{"code": "MONITOR_DOCK","name": "Подключение рабочего места","message": "Внешние мониторы поставляются вместе с док-станцией","expression": {"kind": "OPERATOR","operator": "IMPLIES","args": [{"kind": "OPERATOR","operator": "GT","args": [{"kind": "PARAMETER","parameterCode": "monitors"},{"kind": "CONST","value": 0}]},{"kind": "PARAMETER","parameterCode": "dock"}]}},{"code": "DUAL_MONITOR_POWER","name": "Питание двух мониторов","message": "Комплект с двумя мониторами включает зарядное устройство от 100 Вт","expression": {"kind": "OPERATOR","o