 "lights"},{"kind": "PARAMETER","parameterCode": "plugs"},{"kind": "PARAMETER","parameterCode": "sensors"}]},{"kind": "CONST","value": 1}]},{"kind": "OPERATOR","operator": "LE","args": [{"kind": "OPERATOR","operator": "ADD","args": [{"kind": "PARAMETER","parameterCode": "lights"},{"kind": "PARAMETER","parameterCode": "plugs"},{"kind": "PARAMETER","parameterCode": "sensors"}]},{"kind": "CONST","value": 24}]}]}},{"code": "CAMERA_POWER","name": "Розетка для камеры","message": "Комплект с камерой включает хотя бы одну умную розетку","expression": {"kind": "OPERATOR","operator": "IMPLIES","args": [{"kind": "PARAMETER","parameterCode": "camera"},{"kind": "OPERATOR","operator": "GE","args": [{"kind": "PARAMETER","parameterCode": "plugs"},{"kind": "CONST","value": 1}]}]}}],"variants": [{"code": "SHOP-HOME-START","name": "Умный дом Start · Wi-Fi, 2 лампы и 2 розетки","values": {"protocol": "WIFI","hub": false,"lights": 2,"plugs": 2,"sensors": 0,"camera": false}},{"code": "SHOP-HOME-FLAT","name": "Умный дом для квартиры · шлюз, 4 датчика, камера","values": {"protocol": "MIXED","hub": true,"lights": 4,"plugs": 3,"sensors": 4,"camera": true}},{"code": "SHOP-HOME-HOUSE","name": "Умный дом для дома · Zigbee, 22 устройства","values": {"protocol": "ZIGBEE","hub": true,"lights": 8,"plugs": 6,"sensors": 8,"camera": false}}]},
    {"code": "SHOP-SECURITY","name": "Видеонаблюдение — комплект под объект","parent": "BOM-EL-SEC-DEVICES","parameters": [{"code": "cameras","name": "Количество камер","type": "INTEGER","unit": null,"min": 2,"max": 8,"enumeration": null},{"code": "channels","name": "Каналы регистратора","type": "INTEGER","unit": null,"min": 4,"max": 16,"enumeration": null},{"code": "storage","name": "Объём архива","type": "INTEGER","unit": "GB","min": 1024,"max": 8192,"enumeration": null},{"code": "days","name": "Расчётная глубина архива","type": "INTEGER","unit": "DAY","min": 7,"max": 30,"enumeration": null},{"code": "poe","name": "Питание камер по PoE","type": "BOOLEAN","unit": null,"min": null,"max": null,"enumeration": null},{"code": "poe_budget","name": "Бюджет мощности PoE","type": "INTEGER","unit": "W","min": 0,"max": 240,"enumeration": null}],"rules": [{"code": "AVAILABLE_OPTIONS","name": "Доступное оборудование","message": "Выберите 2/4/8 камер, 4/8/16 каналов, архив 1/2/4/8 ТБ и период 7/14/30 дней","expression": {"kind": "OPERATOR","operator": "AND","args": [{"kind": "OPERATOR","operator": "IN","args": [{"kind": "PARAMETER","parameterCode": "cameras"},{"kind": "CONST","value": [2,4,8]}]},{"kind": "OPERATOR","operator": "IN","args": [{"kind": "PARAMETER","parameterCode": "channels"},{"kind": "CONST","value": [4,8,16]}]},{"kind": "OPERATOR","operator": "IN","args": [{"kind": "PARAMETER","parameterCode": "storage"},{"kind": "CONST","value": [1024,2048,4096,8192]}]},{"kind": "OPERATOR","operator": "IN","args": [{"kind": "PARAMETER","parameterCode": "days"},{"kind": "CONST","value": [7,14,30]}]}]}},{"code": "CHANNEL_CAPACITY","name": "Ёмкость регистратора","message": "Каналов регистратора должно быть не меньше количества камер","expression": {"kind": "CALL","functionCode": "SHOP_MINIMUM","args": [{"kind": "PARAMETER","parameterCode": "channels"},{"kind": "PARAMETER","parameterCode": "cameras"}]}},{"code": "MONTH_ARCHIVE","name": "Месячный архив — политика комплекта","message": "Для 30-дневного комплекта предусмотрено не менее 512 ГБ на камеру","expression": {"kind": "OPERATOR","operator": "IMPLIES","args": [{"kind": "OPERATOR","operator": "EQ","args": [{"kind": "PARAMETER","parameterCode": "days"},{"kind": "CONST","value": 30}]},{"kind": "CALL","functionCode": "SHOP_MINIMUM","args": [{"kind": "PARAMETER","parameterCode": "storage"},{"kind": "OPERATOR","operator": "MUL","args": [{"kind": "PARAMETER","parameterCode": "cameras"},{"kind": "CONST","value": 512}]}]}]}},{"code": "POE_POWER","name": "Запас мощности PoE","message": "При PoE бюджет должен обеспечивать 12 Вт на камеру и запас 25%; без PoE бюджет равен 0","expression": {"kind": "OPERATOR","operator": "OR","args": [{"kind": "OPERATOR","operator": "AND","args": [{"kind": "PARAMETER","parameterCode": "poe"},{"kind": "CALL","functionCode": "SHOP_POWER_RESERVE","args": [{"kind": "PARAMETER","parameterCode": "poe_budget"},{"kind": "OPERATOR","operator": "MUL","args": [{"kind": "PARAMETER","parameterCode": "cameras"},{"kind": "CONST","value": 12}]}]}]},{"kind": "OPERATOR","operator": "AND","args": [{"kind": "OPERATOR","operator": "NOT","args": [{"kind": "PARAMETER","parameterCode": "poe"}]},{"kind": "OPERATOR","operator": "EQ","args": [{"kind": "PARAMETER","parameterCode": "poe_budget"},{"kind": "CONST","value": 0}]}]}]}}],"variants": [{"code": "SHOP-SECURITY-SMALL","name": "Видеонаблюдение для дома · 2 камеры, архив 1 ТБ","values": {"cameras": 2,"channels": 4,"storage": 1024,"days": 7,"poe": true,"poe_budget": 60}},{"code": "SHOP-SECURITY-OFFICE","name": "Видеонаблюдение для офиса · 4 камеры, архив 2 ТБ","values": {"cameras": 4,"channels": 8,"storage": 2048,"days": 14,"poe": true,"poe_budget": 120}},{"code": "SHOP-SECURITY-BUSINESS","name": "Видеонаблюдение для бизнеса · 8 камер, архив 4 ТБ","values": {"cameras": 8,"channels": 16,"storage": 4096,"days": 30,"poe": true,"poe_budget": 240}}]}
  ],
  "customers": [
    {"key": "ANNA","name": "Анна Крылова","contact": null,"phone": "+7 000 700-01-01","email": "anna.krylova@example.test"},
    {"key": "IVAN","name": "Иван Морозов","contact": null,"phone": "+7 000 700-01-02","email": "ivan.morozov@example.test"},
    {"key": "NORTH","name": "ООО «Северный проект»","contact": "Елена Павлова, закупки","phone": "+7 000 700-01-03","email": "purchase@north-project.example.test"},
    {"key": "MARINA","name": "ИП Соколова Марина","contact": "Марина Соколова","phone": "+7 000 700-01-04","email": "store@sokolova.example.test"},
    {"key": "DMITRY","name": "Дмитрий Лебедев","contact": null,"phone": "+7 000 700-01-05","email": "dmitry.lebedev@example.test"},
    {"key": "OLGA","name": "Ольга Смирнова","contact": null,"phone": "+7 000 700-01-06","email": "olga.smirnova@example.test"},
    {"key": "SPACE","name": "ООО «Рабочее пространство»","contact": "Алексей Орлов, администратор","phone": "+7 000 700-01-07","email": "office@workspace.example.test"},
    {"key": "GRIGORY","name": "Григорий Волков","contact": null,"phone": "+7 000 700-01-08","email": "grigory.volkov@example.test"}
  ],
  "orders": [
    {"number": "SHOP-2026-0101","customer": "ANNA","age": 10,"due": 3,"lines": [{"variant": "SHOP-PHONE-EVERYDAY","quantity": 1,"note": "Смартфон для повседневного использования; проверить синий цвет"},{"product": "BOM-EL-PHONE-POWERBANK","quantity": 1,"note": "Для поездок и зарядки в дороге"}]},
    {"number": "SHOP-2026-0102","customer": "IVAN","age": 9,"due": 5,"lines": [{"variant": "SHOP-PC-GAMING","quantity": 1,"note": "Сборка и проверка перед выдачей"},{"variant": "SHOP-GAMING-WIRED","quantity": 1,"note": null},{"product": "BOM-EL-GAME-MAT","quantity": 1,"note": null}]},
    {"number": "SHOP-2026-0103","customer": "NORTH","age": 7,"due": 14,"lines": [{"variant": "SHOP-WORKPLACE-OFFICE","quantity": 8,"note": "Одинаковые рабочие места для проектного отдела"},{"variant": "SHOP-PHONE-BASIC","quantity": 2,"note": "Служебные телефоны"},{"product": "BOM-EL-GAME-WIRELESS-MOUSE","quantity": 8,"note": null}]},
    {"number": "SHOP-2026-0104","customer": "MARINA","age": 5,"due": 10,"lines": [{"variant": "SHOP-SECURITY-OFFICE","quantity": 1,"note": "Видеонаблюдение для небольшого магазина"},{"product": "BOM-EL-SEC-CABLE","quantity": 30,"note": "Количество кабеля в метрах"},{"product": "BOM-EL-SEC-HDD2","quantity": 1,"note": "Резервный накопитель для обслуживания"}]},
    {"number": "SHOP-2026-0105","customer": "DMITRY","age": 4,"due": 7,"lines": [{"variant": "SHOP-PC-PRO","quantity": 1,"note": "Монтаж видео и игры"},{"variant": "SHOP-GAMING-DUAL","quantity": 1,"note": "Английская раскладка согласована"}]},
    {"number": "SHOP-2026-0106","customer": "OLGA","age": 3,"due": 5,"lines": [{"variant": "SHOP-HOME-FLAT","quantity": 1,"note": "Для трёхкомнатной квартиры"},{"product": "BOM-EL-HOME-BULB","quantity": 2,"note": "Дополнительные лампы сверх комплекта"},{"variant": "SHOP-PHONE-BASIC","quantity": 1,"note": null}]},
    {"number": "SHOP-2026-0107","customer": "SPACE","age": 2,"due": 12,"lines": [{"variant": "SHOP-WORKPLACE-MOBILE","quantity": 5,"note": "Комплекты для выездной команды"},{"variant": "SHOP-HOME-HOUSE","quantity": 2,"note": "Два этажа коворкинга"},{"variant": "SHOP-SECURITY-BUSINESS","quantity": 1,"note": "Входная зона и общие помещения"},{"product": "BOM-EL-SEC-CABLE","quantity": 60,"note": "Количество кабеля в метрах"}]},
    {"number": "SHOP-2026-0108","customer": "GRIGORY","age": 0,"due": 4,"lines": [{"variant": "SHOP-PHONE-TRAVEL","quantity": 1,"note": "Комплект для путешествий с усиленным чехлом"},{"variant": "SHOP-HOME-START","quantity": 1,"note": null},{"product": "ASSORT-USB-C-CABLE","quantity": 2,"note": "Две упаковки по два кабеля"}]}
  ]
}$dataset$::jsonb;
 item JSONB; param JSONB; entry JSONB; choice JSONB; line JSONB;
 cls BIGINT; enum_id BIGINT; parent BIGINT; model BIGINT; template BIGINT;
 cust BIGINT; ord BIGINT; variant BIGINT; product BIGINT; unit BIGINT;
 templates JSONB := '{}'; variants JSONB := '{}'; customers JSONB := '{}';
BEGIN
 PERFORM pg_advisory_xact_lock(21001);
 IF EXISTS(SELECT 1 FROM schema_migration WHERE name='orders-shop-demo-v1') THEN RETURN; END IF;
 -- Сначала проверяем зависимости: минимальная тестовая БД и собственный пустой каталог допустимы.
 IF EXISTS(SELECT 1 FROM (VALUES
  ('BOM-EL-KITS','GROUP'),('LAPTOPS','GROUP'),('PHONES','GROUP'),
  ('BOM-EL-GAME-DEVICES','GROUP'),('BOM-EL-HOME-DEVICES','GROUP'),('BOM-EL-SEC-DEVICES','GROUP'),
  ('BOM-EL-PHONE-POWERBANK','PRODUCT'),('BOM-EL-GAME-MAT','PRODUCT'),
  ('BOM-EL-GAME-WIRELESS-MOUSE','PRODUCT'),('BOM-EL-SEC-CABLE','PRODUCT'),
  ('BOM-EL-SEC-HDD2','PRODUCT'),('BOM-EL-HOME-BULB','PRODUCT'),('ASSORT-USB-C-CABLE','PRODUCT')
 ) required(code,kind) WHERE NOT EXISTS(SELECT 1 FROM classifier_node n WHERE n.code=required.code AND n.node_kind=required.kind))
 OR NOT EXISTS(SELECT 1 FROM enumeration WHERE code='PHONE-COLORS') THEN
  RAISE NOTICE 'Примеры заказов магазина ожидают демонстрационный каталог электроники'; RETURN;
 END IF;
 -- Не смешиваем набор с пользовательскими записями, занявшими зарезервированные коды.
 IF EXISTS(SELECT 1 FROM classifier_node WHERE code IN (SELECT 'SHOP-MODEL-'||substr(value->>'code',6) FROM jsonb_array_elements(data->'templates')))
 OR EXISTS(SELECT 1 FROM product_template WHERE code IN (SELECT value->>'code' FROM jsonb_array_elements(data->'templates')))
 OR EXISTS(SELECT 1 FROM product_variant WHERE code LIKE 'SHOP-%')
 OR EXISTS(SELECT 1 FROM constraint_function WHERE code IN (SELECT value->>'code' FROM jsonb_array_elements(data->'functions')))
 OR EXISTS(SELECT 1 FROM enumeration WHERE code IN (SELECT value->>'code' FROM jsonb_array_elements(data->'enumerations')))
 OR EXISTS(SELECT 1 FROM enumeration_class WHERE code='SHOP-CONFIGURATION')
 OR EXISTS(SELECT 1 FROM customer_order WHERE order_number IN (SELECT value->>'number' FROM jsonb_array_elements(data->'orders'))) THEN
  RAISE NOTICE 'Набор магазина пропущен: его коды уже заняты; существующие записи сохранены'; RETURN;
 END IF;
 INSERT INTO unit_of_measure(code,name) VALUES('PCS','штуки'),('GB','ГБ'),('W','ватты'),('H','часы'),('DAY','дни') ON CONFLICT(code) DO NOTHING;
 INSERT INTO enumeration_class(code,name,created_at,updated_at) VALUES('SHOP-CONFIGURATION','Комплектации магазина',now(),now()) RETURNING id INTO cls;
 FOR item IN SELECT value FROM jsonb_array_elements(data->'enumerations') LOOP
  INSERT INTO enumeration(code,name,enumeration_class_id,created_at,updated_at) VALUES(item->>'code',item->>'name',cls,now(),now()) RETURNING id INTO enum_id;
  FOR choice IN SELECT value FROM jsonb_array_elements(item->'values') LOOP
   INSERT INTO enumeration_value(enumeration_id,code,name,sort_order,created_at,updated_at)
   VALUES(enum_id,choice->>'code',choice->>'name',(SELECT count(*) FROM enumeration_value WHERE enumeration_id=enum_id),now(),now());
  END LOOP;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(data->'functions') LOOP
  PERFORM orders_save_function(NULL,item->>'code',item->>'name','BOOLEAN',item->'parameters',item->'expression');
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(data->'templates') LOOP
  SELECT id INTO STRICT parent FROM classifier_node WHERE code=item->>'parent';
  SELECT id INTO STRICT unit FROM unit_of_measure WHERE code='PCS';
  INSERT INTO classifier_node(code,name,node_kind,parent_id,unit_of_measure_id,sort_order,created_at,updated_at)
  VALUES('SHOP-MODEL-'||substr(item->>'code',6),item->>'name','MODEL',parent,unit,20,now(),now()) RETURNING id INTO model;
  INSERT INTO product_template(product_id,code,name) VALUES(model,item->>'code',item->>'name') RETURNING id INTO template;
  templates:=templates||jsonb_build_object(item->>'code',template);
  FOR param IN SELECT value FROM jsonb_array_elements(item->'parameters') LOOP
   INSERT INTO configuration_parameter(template_id,code,name,data_type,unit_of_measure_id,enumeration_id,required,min_value,max_value)
   VALUES(template,param->>'code',param->>'name',param->>'type',
    (SELECT id FROM unit_of_measure WHERE code=param->>'unit'),(SELECT id FROM enumeration WHERE code=param->>'enumeration'),true,(param->>'min')::numeric,(param->>'max')::numeric);
  END LOOP;
  FOR entry IN SELECT value FROM jsonb_array_elements(item->'rules') LOOP
   PERFORM orders_save_rule(NULL,template,entry->>'code',entry->>'name',entry->>'message',entry->'expression');
  END LOOP;
  FOR entry IN SELECT value FROM jsonb_array_elements(item->'variants') LOOP
   variant:=create_variant(template,entry->>'code',entry->>'name',entry->'values');
   variants:=variants||jsonb_build_object(entry->>'code',variant);
  END LOOP;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(data->'customers') LOOP
  INSERT INTO customer(name,contact_person,phone,email) VALUES(item->>'name',item->>'contact',item->>'phone',item->>'email') RETURNING id INTO cust;
  customers:=customers||jsonb_build_object(item->>'key',cust);
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(data->'orders') LOOP
  ord:=create_order((customers->>(item->>'customer'))::bigint,item->>'number',CURRENT_DATE-(item->>'age')::int,CURRENT_DATE-(item->>'age')::int+(item->>'due')::int);
  FOR line IN SELECT value FROM jsonb_array_elements(item->'lines') LOOP
   variant:=(variants->>(line->>'variant'))::bigint;
   product:=NULL;IF line ? 'product' THEN SELECT id INTO STRICT product FROM classifier_node WHERE code=line->>'product'; END IF;
   PERFORM add_to_order(ord,product,variant,(line->>'quantity')::int,line->>'note');
  END LOOP;
 END LOOP;
 PERFORM orders_assert_consistent();
 INSERT INTO schema_migration(name,details) VALUES('orders-shop-demo-v1',jsonb_build_object('templates',templates,'variants',variants,'customers',customers));
END $shop$;
